insert into public.observations (region_code, indicator_id, dataset_id, period_label, year, value, source_id, source_table, source_page, date_pulled, archive_url, break_before, note) values ('TG', 'literacy', 'census_literacy_state', '2011', 2011, 66.54, 'tg-seo-2023', 'Annexure 17 (f): Literacy Rate of Population from 1961 to 2011, Telangana Socio Economic Outlook 2023', '272', '2026-10-16', null, false, 'Census 2011; persons; population aged 7+ (Annexure 21 title: Literate Population (7 Years and above)); printed value, source line ''Registrar General and Census Commissioner, India''; printed page 268; same 66.54 in Annexure 22 State row (PDF p. 277). Present-day Telangana: Annexure 17(a) prints 2011 population 3,50,03,674, which is 190,304 fewer than the 10 districts as constituted in 2011 (PCA sum 35,193,978; that 2011-boundary calculation would give 66.46). Check: Annexure 21 literates 2,06,96,778 / (3,50,03,674 - Annexure 18 child population 0-6 38,99,166) = 66.54.');
